const items = $input.all();
const recipes = [];

for (const item of items) {
  const htmlContent = item.json.data;

  if (!htmlContent) continue;

  // Extraire le JSON-LD du HTML
  const regex = /<script type="application\/ld\+json"[^>]*>\s*([\s\S]*?)\s*<\/script>/g;
  let match;

  while ((match = regex.exec(htmlContent)) !== null) {
    try {
      const jsonData = JSON.parse(match[1]);

      // CORRECTION : chercher dans le @graph
      let recipeData = null;

      if (jsonData['@type'] === 'Recipe') {
        recipeData = jsonData;
      } else if (jsonData['@graph']) {
        // Chercher dans le graph
        recipeData = jsonData['@graph'].find(item => item['@type'] === 'Recipe');
      }

      if (recipeData) {
        const formatted = {
          titre: recipeData.name,
          description: recipeData.description,
          categorie: recipeData.recipeCategory,
          temps_preparation: recipeData.prepTime,
          temps_cuisson: recipeData.cookTime,
          temps_total: recipeData.totalTime,
          portions: recipeData.recipeYield,
          ingredients: recipeData.recipeIngredient || [],
          etapes: (recipeData.recipeInstructions || []).map(step => 
            typeof step === 'string' ? step : (step.text || '')
          ),
          auteur: recipeData.author?.name || recipeData.author,
          image: recipeData.image?.[0] || recipeData.image,
          note: recipeData.aggregateRating ? {
            valeur: recipeData.aggregateRating.ratingValue,
            nombre_avis: recipeData.aggregateRating.reviewCount
          } : null
        };

        recipes.push(formatted);
      }
    } catch (e) {
      console.error('Erreur parsing JSON-LD:', e.message);
    }
  }
}

console.log('Recettes trouvées:', recipes.length);

return [{
  json: {
    recettes: recipes,
    nombre_recettes: recipes.length
  }
}];

const output = $input.item.json.output;

// Retire les balises markdown
let cleanOutput = output
  .replace(/```json\s*/g, '')
  .replace(/```\s*/g, '')
  .replace(/\n/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

// LOG pour déboguer
console.log('JSON nettoyé:', cleanOutput);
console.log('Position 1048:', cleanOutput.substring(1040, 1060));

let recipe;
try {
  recipe = JSON.parse(cleanOutput);
} catch (e) {
  const pos = parseInt(e.message.match(/position (\d+)/)?.[1] || 0);
  console.error('Position erreur:', pos);
  console.error('Contexte:', cleanOutput.substring(pos - 50, pos + 50));

  // Tentative de correction automatique des erreurs courantes
  cleanOutput = cleanOutput
    .replace(/,(\s*[}\]])/g, '$1')      // Retire virgules avant } ou ]
    .replace(/([}\]])(\s*)([{\[])/g, '$1,$2$3')  // Ajoute virgules manquantes
    .replace(/"([^"]*)"(\s*)"([^"]*)"/g, '"$1 $3"');  // Fusionne strings cassées

  try {
    recipe = JSON.parse(cleanOutput);
    console.log('JSON corrigé automatiquement');
  } catch (e2) {
    throw new Error(`JSON invalide même après correction: ${e2.message}`);
  }
}

const items = [
  { json: { ...recipe, _type: 'recipe' } }
];

if (recipe.ingredients && Array.isArray(recipe.ingredients)) {
  recipe.ingredients.forEach(ing => {
    items.push({ 
      json: { 
        ...ing, 
        _type: 'ingredient',
        recipe_title: recipe.title 
      }
    });
  });
}

return items;

const matchedIngredients = $input.all();

function normalizeText(text) {
  if (!text) return '';

  return text
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[''`]/g, "'")
    .replace(/œ/g, 'oe')
    .replace(/æ/g, 'ae')
    .replace(/\s+/g, ' ')
    .trim();
}

function slugify(text) {
  if (!text) return '';

  return text
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/œ/g, 'oe')
    .replace(/æ/g, 'ae')
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
}

function getBaseForm(text) {
  const normalized = normalizeText(text);

  const variations = {
    'pommes de terre': 'pomme-de-terre',
    'pomme de terre': 'pomme-de-terre',
    'pdt': 'pomme-de-terre',
    'patates': 'pomme-de-terre',
    'pommes': 'pomme',
    'oeufs': 'oeuf',
    'tomates': 'tomate',
    'oignons': 'oignon',
    'gousses d\'ail': 'ail',
    'gousse d\'ail': 'ail',
    'pates': 'pate',
    'coquillettes': 'pate',
    'spaghettis': 'pate',
    'escalope de poulet': 'poulet',
    'escalopes de poulet': 'poulet',
    'filet de poulet': 'poulet',
    'filets de poulet': 'poulet',
    'blanc de poulet': 'poulet',
    'blancs de poulet': 'poulet',
    'cuisse de poulet': 'poulet',
    'cuisses de poulet': 'poulet',
    'filet de saumon': 'saumon',
    'pave de saumon': 'saumon',
    'boite de thon': 'thon',
    'fromage rape': 'fromage',
    'emmental rape': 'emmental',
    'gruyere rape': 'gruyere',
    'pain de mie': 'pain',
    'baguette': 'pain',
    'creme fraiche': 'creme',
    'creme liquide': 'creme',
    'beurre doux': 'beurre',
    'beurre demi-sel': 'beurre',
    'huile d\'olive': 'huile',
    'concentre de tomate': 'tomate',
    'tomates concassees': 'tomate',
    'coulis de tomate': 'tomate'
  };

  if (variations[normalized]) {
    return variations[normalized];
  }

  let cleaned = normalized
    .replace(/^(un|une|des|du|de la|le|la|les)\s+/g, '')
    .replace(/\s+(de|d'|en)\s+/g, ' ')
    .replace(/\s+(frais|fraiche|rape|concasse|hache|tranche|entier|entiere)$/g, '');

  if (variations[cleaned]) {
    return variations[cleaned];
  }

  return slugify(cleaned.replace(/s$/, ''));
}

return matchedIngredients.map(item => ({
  json: {
    ...item.json,
    normalized_search: getBaseForm(item.json.name)
  }
}));

const matchedIngredients = $input.all();

return [{
  json: {
    matched_ingredients: matchedIngredients.map(item => ({
      name: item.json.ingredient_name || item.json.name,
      quantity: item.json.quantity,
      unit: item.json.unit,
      _type: "ingredient",
      recipe_title: item.json.recipe_title,
      ingredient_id: item.json.ingredient_id
    }))
  }
}];

return $input.all().map(item => ({
  json: {
    original_ingredient: item.json.name || item.json.original_name,
    quantity: item.json.quantity,
    unit: item.json.unit,
    ingredient_id: item.json.id,
    ingredient_name: item.json.name,
    ingredient_slug: item.json.slug,
    similarity_score: item.json.similarity_score
  }
}));
